def geri_bildirimlerden_doldur(apps, schema_editor):
    """Daha önce gelmiş kalıcı bounce / şikâyetler de engellensin (yalnız ileriye değil)."""
    Geri = apps.get_model("accounts", "EpostaGeriBildirim")
    Engel = apps.get_model("accounts", "EpostaEngeli")
    for g in Geri.objects.filter(tur__in=["bounce", "sikayet"]).order_by("created_at"):
        email = (g.email or "").strip().lower()
        if not email:
            continue
        satir, yeni = Engel.objects.get_or_create(
            email=email, defaults={"sebep": g.tur, "aciklama": (g.alt_tur or "")[:500]})
        if not yeni:
            satir.sayac += 1
            satir.sebep = g.tur
            satir.save(update_fields=["sayac", "sebep"])


